const START='2026-11-23', DEADLINE='2027-01-31';
const CATS={
 quant:{name:'GRE Quant',color:'#5969ec',study:true},verbal:{name:'GRE Verbal',color:'#9880dc',study:true},ielts:{name:'IELTS',color:'#19a692',study:true},python:{name:'Python',color:'#e0a442',study:true},career:{name:'Career course',color:'#6095cb',study:true},grammar:{name:'Grammar',color:'#af8fbe',study:true},
 gym:{name:'Gym / sauna',color:'#dd825d',study:false},walk:{name:'Walking',color:'#6aa77d',study:false},stretch:{name:'Stretching',color:'#92b07a',study:false},sing:{name:'Singing',color:'#cc82b2',study:false},draw:{name:'Drawing',color:'#9c92cf',study:false},read:{name:'Reading',color:'#8aabd6',study:false},sleep:{name:'Sleep',color:'#67799b',study:false},rest:{name:'Rest / meals',color:'#b4becd',study:false},leisure:{name:'Leisure',color:'#9da9b8',study:false},other:{name:'Other',color:'#8995a6',study:false}
};
