const FOUNDATIONS=[
 ['Inequalities & absolute values',120],['Sequences & series',70],['Sets & Venn diagrams',75],['Geometry: introduction',60],['Geometry: continued',95],['Numbers',90],['Numbers: continued',120],['Coordinate geometry',120],['Equations & ratios: part 1',85],['Equations & ratios: part 2',60],['Statistics',100],['Percentages',60],['Rate & time',90],['Permutations & combinations',100],['Probability',120],['Interest',90],['Exponents',40]
];
const WK_DEFS=[
 {q:[1,2],v:[1],f:[1,2],focus:'Start with inequalities, diagnostics and sequences. Leave time to establish your routine.'},
 {q:[3],v:[2,3],f:[3,4],focus:'Lighter Quant class week; spend more class time on Verbal and prepare geometry.'},
 {q:[4,5],v:[4],f:[5,6,17],focus:'Geometry + numbers. Complete exponent foundations before number practice.'},
 {q:[6],v:[5,6],f:[7,8],focus:'Numbers + 3D geometry. Preview coordinate geometry for next week.'},
 {q:[7,8],v:[7],f:[9,10,11],focus:'Coordinate geometry, equations, ratios and the first statistics topics.'},
 {q:[9],v:[8,9],f:[12,13],focus:'Finish statistics; prep percentages and rate/time before Week 7.'},
 {q:[10,11],v:[10],f:[14,15],focus:'Percentage/rate and P&C; preview probability for Week 8.'},
 {q:[12],v:[11,12],f:[16],focus:'Probability and interest. Complete final Verbal sessions.'},
 {q:[13],v:[],f:[],focus:'Interest, data interpretation, pending post-work and mixed Quant + Verbal review.'},
 {q:[],v:[],f:[],focus:'Mock exams, timed sets and error review. No new syllabus unless necessary.'}
];
const CHECKS=['Reviewed GRE errors and difficult questions','Completed IELTS speaking/writing/listening/reading practice','Kept one lighter/recovery period','Prioritized sleep instead of late-night catch-up','Reviewed and adjusted next week’s workload'];
const block=(label,cat,start,minutes)=>({id:uid(),label,category:cat,start,minutes});
function makeTemplates(){return {
 morning:{name:'Morning gym',description:'Four gym days · combined gym shower and morning bath',blocks:[
 block('Morning stretching','stretch','06:30',40),block('Gym + sauna + bath','gym','07:10',90),block('Breakfast','rest','08:40',30),block('GRE focused block 1','quant','09:10',135),block('Walking break','walk','11:25',20),block('GRE focused block 2','verbal','11:45',120),block('Lunch and rest','rest','13:45',35),block('IELTS class + practice','ielts','14:20',120),block('Walk and break','walk','16:20',30),block('Other enrolled course','career','16:50',120),block('Dinner + short walk','rest','18:50',35),block('Python sprint','python','19:25',90),block('Singing practice','sing','20:55',30),block('Drawing, reading or leisure','leisure','21:25',35),block('Bedtime routine','rest','22:00',30),block('Sleep','sleep','22:30',480)]},
 afternoon:{name:'4 PM gym',description:'Separate 30-min morning bath · gym at 4 PM',blocks:[
 block('Morning stretching','stretch','06:30',40),block('Morning bath','rest','07:10',30),block('Breakfast','rest','07:40',30),block('GRE focused block 1','quant','08:10',135),block('Walking break','walk','10:25',20),block('GRE focused block 2','verbal','10:45',120),block('Lunch','rest','12:45',35),block('Other enrolled course','career','13:20',120),block('Walk + gym preparation','walk','15:20',40),block('Gym + sauna + shower','gym','16:00',90),block('IELTS class + practice','ielts','17:30',120),block('Dinner + short walk','rest','19:30',35),block('Python sprint','python','20:05',60),block('Singing practice','sing','21:05',30),block('Reading or entertainment','leisure','21:35',25),block('Bedtime routine','rest','22:00',30),block('Sleep','sleep','22:30',480)]},
 recovery:{name:'Wednesday recovery',description:'Gym-free day · extra buffer or rest',blocks:[
 block('Morning stretching','stretch','06:30',40),block('Morning bath','rest','07:10',30),block('Breakfast + calm start','rest','07:40',60),block('GRE focused block 1','quant','08:40',135),block('Walking break','walk','10:55',20),block('GRE focused block 2','verbal','11:15',120),block('Lunch + rest','rest','13:15',45),block('IELTS class + practice','ielts','14:00',120),block('Walk / outdoors','walk','16:00',30),block('Other enrolled course','career','16:30',120),block('Dinner + break','rest','18:30',50),block('Python / flexible buffer','python','19:20',90),block('Singing practice','sing','20:50',30),block('Free time and reading','leisure','21:20',40),block('Bedtime routine','rest','22:00',30),block('Sleep','sleep','22:30',480)]},
 weekend:{name:'Weekend revision',description:'Daytime classes + singing already booked until 6 PM',blocks:[
 block('Stretch + morning bath + breakfast','stretch','06:30',90),block('Weekend classes + singing (adjust actual start)','other','08:00',600),block('Dinner + rest','rest','18:00',45),block('GRE revision and error log','quant','18:45',120),block('IELTS revision','ielts','20:45',30),block('Entertainment, reading or drawing','leisure','21:15',45),block('Bedtime routine','rest','22:00',30),block('Sleep','sleep','22:30',480)]}
};}
function seedSyllabus(){const a=[];FOUNDATIONS.forEach(([name,minutes],i)=>a.push({id:`f${i+1}`,subject:'quant',stage:'foundation',code:`F${i+1}`,title:name,minutes:minutes*2,rawMinutes:minutes,completed:false,note:''}));
 QUANT_CLASSES.forEach((name,i)=>{a.push({id:`q${i+1}`,subject:'quant',stage:'in',code:`C${i+1}`,title:name,minutes:240,completed:false,note:''});a.push({id:`qp${i+1}`,subject:'quant',stage:'post',code:`C${i+1} POST`,title:`Practice & assignment: Class ${i+1}`,minutes:150,completed:false,note:''});});
 for(let i=1;i<=12;i++){a.push({id:`vp${i}`,subject:'verbal',stage:'pre',code:`V${i} PRE`,title:`Verbal Class ${i}: pre-class preparation`,minutes:30,completed:false,note:''});a.push({id:`v${i}`,subject:'verbal',stage:'in',code:`V${i}`,title:`Verbal Class ${i} — edit to add your actual topic`,minutes:270,completed:false,note:''});a.push({id:`vpost${i}`,subject:'verbal',stage:'post',code:`V${i} POST`,title:`Verbal Class ${i}: post-class assignment`,minutes:35,completed:false,note:''});}
 return a;}
function seedWeeks(){return WK_DEFS.map((x,i)=>({id:i+1,q:[...x.q],v:[...x.v],f:[...x.f],focus:x.focus,goalQ:i===9?12:(i===8?14:(i%2===0?14:9)),goalV:i===9?12:(i===8?11:(i%2===0?11.25:16.25)),goalIELTS:11,goalCareer:10,goalPython:i<2?7.5:0,checks:{},note:''}));}
function freshState(){return {version:1,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),lastBackupAt:null,templates:makeTemplates(),assignment:{0:'weekend',1:'morning',2:'morning',3:'recovery',4:'morning',5:'morning',6:'weekend'},syllabus:seedSyllabus(),weeks:seedWeeks(),logs:[],notes:{},timer:null,settings:{dailyGoal:480,allowNotifications:false}};}
function hydrate(source){if(!source||typeof source!=='object'||!Array.isArray(source.syllabus)||!Array.isArray(source.logs))throw Error('Not a compatible Focus Atlas backup');const def=freshState();return {...def,...source,templates:{...def.templates,...(source.templates||{})},assignment:{...def.assignment,...(source.assignment||{})},settings:{...def.settings,...(source.settings||{})},weeks:Array.isArray(source.weeks)?source.weeks:def.weeks,notes:(source.notes&&typeof source.notes==='object')?source.notes:{},timer:source.timer||null};}
function uid(){return globalThis.crypto?.randomUUID?.()||`id-${Date.now()}-${Math.random().toString(36).slice(2,9)}`;}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const parseDay=d=>new Date(`${d}T12:00:00`);
const dayAdd=(s,n)=>{const d=parseDay(s);d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const toMinutes=t=>{let [h,m]=String(t||'00:00').split(':').map(Number);return h*60+m};
const toClock=n=>`${String(Math.floor(((n%1440)+1440)%1440/60)).padStart(2,'0')}:${String(((n%1440)+1440)%1440%60).padStart(2,'0')}`;
const duration=n=>{n=Math.max(0,Math.round(n||0));return `${Math.floor(n/60)}h ${String(n%60).padStart(2,'0')}m`};
const hr=n=>(Math.round(n/6)/10).toFixed(1);
const percent=(n,d)=>d?Math.min(100,Math.max(0,Math.round(n/d*100))):0;
const fullDate=s=>parseDay(s).toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long',year:'numeric'});
const shortDate=s=>parseDay(s).toLocaleDateString(undefined,{day:'numeric',month:'short'});
const monthDay=s=>parseDay(s).toLocaleDateString(undefined,{month:'short',day:'numeric'});
const weekday=s=>parseDay(s).getDay();
const weekNo=d=>Math.min(10,Math.max(1,Math.floor((parseDay(d)-parseDay(START))/86400000/7)+1));
const weekStart=i=>dayAdd(START,(i-1)*7);
const getCat=c=>CATS[c]||CATS.other;
const catOptions=(selected,studyOnly=false)=>Object.entries(CATS).filter(([k,v])=>!studyOnly||v.study).map(([k,v])=>`<option value="${k}" ${selected===k?'selected':''}>${esc(v.name)}</option>`).join('');
const stageLabel=s=>({foundation:'Foundation webinar',pre:'Pre-class',in:'In-class',post:'Post-class'}[s]||s);
const syllabusItem=id=>state.syllabus.find(x=>x.id===id);
const unitDone=(type,n)=>type==='quant'?['q'+n,'qp'+n].every(id=>syllabusItem(id)?.completed):['vp'+n,'v'+n,'vpost'+n].every(id=>syllabusItem(id)?.completed);
const sum=(arr,field='minutes')=>arr.reduce((a,x)=>a+(Number(x[field])||0),0);
function studyLogs(list){return list.filter(l=>getCat(l.category).study)}
function minutesFor(list,cat){return sum(cat?list.filter(x=>x.category===cat):list)}
function minutesInRange(from,to){return state.logs.filter(x=>x.date>=from&&x.date<=to)}
function plannedTotal(blocks,studyOnly=true){return blocks.reduce((a,b)=>a+(studyOnly&&!getCat(b.category).study?0:Math.max(0,Number(b.minutes)||0)),0)}
function scheduledForDate(s){const key=state.assignment[weekday(s)]||'morning';return {key,...state.templates[key]};}
function currentWeek(){return state.weeks[weekNo(today())-1]||state.weeks[0]}
function progress(subject){let x=state.syllabus.filter(z=>!subject||z.subject===subject);return {done:x.filter(z=>z.completed).length,total:x.length,pct:percent(x.filter(z=>z.completed).length,x.length),worked:x.filter(z=>z.completed).reduce((a,z)=>a+z.minutes,0),planned:sum(x)}}
const $=s=>document.querySelector(s);
let state,ui={page:'dashboard',template:'morning',editSchedule:false,syllabusSubject:'all',syllabusStage:'all',syllabusSearch:'',noteDate:today(),logDate:today(),week:weekNo(today()),statsRange:'7',statsFrom:dayAdd(today(),-6),statsTo:today()},dbPromise=null,saveTimer=null,saveQueue=Promise.resolve(),toastTimer=null;
function openDB(){if(dbPromise)return dbPromise;dbPromise=new Promise((resolve,reject)=>{if(!('indexedDB' in window))return reject(Error('IndexedDB unavailable'));const req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>req.result.createObjectStore(DB_STORE);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});return dbPromise;}
async function dbRead(){const db=await openDB();return new Promise((resolve,reject)=>{const r=db.transaction(DB_STORE,'readonly').objectStore(DB_STORE).get(APP_KEY);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function dbWrite(value){const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readwrite');tx.objectStore(DB_STORE).put(value,APP_KEY);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);});}
function localRead(){try{return JSON.parse(localStorage.getItem(APP_KEY)||'null')}catch{return null}}
function localWrite(value){try{localStorage.setItem(APP_KEY,JSON.stringify(value));return true}catch{return false}}
async function load(){let a=null,b=null;try{a=await dbRead()}catch(e){console.warn('IndexedDB unavailable, using browser storage.',e)}b=localRead();const chosen=(!a?b:!b?a:(String(b.updatedAt||'')>String(a.updatedAt||'')?b:a));try{return chosen?hydrate(chosen):freshState()}catch(e){console.error('Stored workspace could not be read:',e);return freshState()}}
function persist(){state.updatedAt=new Date().toISOString();$('#saveIndicator')?.replaceChildren(document.createTextNode('● Saving…'));clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{const snapshot=JSON.parse(JSON.stringify(state));saveQueue=saveQueue.then(async()=>{const localOK=localWrite(snapshot);let dbOK=false;try{await dbWrite(snapshot);dbOK=true}catch(e){console.warn('IndexedDB save failed',e)}const el=$('#saveIndicator');if(el)el.textContent=localOK||dbOK?'● Saved on this device':'● Storage unavailable — export a backup';});await saveQueue;},180);}
function flushSave(){clearTimeout(saveTimer);if(!state)return;const snapshot=JSON.parse(JSON.stringify(state));localWrite(snapshot);saveQueue=saveQueue.then(()=>dbWrite(snapshot).catch(()=>{}));}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3000);}
function navigate(name){ui.page=name;$('#sidebar').classList.remove('shown');document.querySelectorAll('.nav-item').forEach(e=>e.classList.toggle('active',e.dataset.page===name));render();window.scrollTo({top:0,behavior:'instant'});}
function pageHeading(kicker,title,sub,actions=''){return `<div class="page-header"><div><p class="eyebrow">${esc(kicker)}</p><h1>${esc(title)}</h1>${sub?`<p class="subtitle">${esc(sub)}</p>`:''}</div>${actions?`<div class="header-actions">${actions}</div>`:''}</div>`;}
function meter(label,current,total,color){return `<div class="meter-row"><div class="row-between"><span>${esc(label)}</span><strong>${current} / ${total}</strong></div><div class="progress-track"><i style="width:${percent(current,total)}%;background:${color||'var(--brand)'}"></i></div></div>`}
function render(){if(!state)return;const pages={dashboard:renderDashboard,planner:renderPlanner,log:renderLog,syllabus:renderSyllabus,weeks:renderWeeks,notes:renderNotes,stats:renderStats,settings:renderSettings};const names={dashboard:'Overview',planner:'Daily schedules',log:'Timer & activity',syllabus:'GRE syllabus',weeks:'Weekly roadmap',notes:'Daily notes',stats:'Statistics',settings:'Settings & backup'};$('#crumbPage').textContent=names[ui.page]||'Overview';$('#view').innerHTML=(pages[ui.page]||renderDashboard)();let d=Math.max(0,Math.ceil((parseDay(DEADLINE)-parseDay(today()))/86400000));$('#daysLeftSide').textContent=`${d} days remaining · GRE + IELTS`;
 $('#sideProg').style.width=progress().pct+'%';refreshTimerDisplay();}
function renderDashboard(){const date=today(),todayLog=minutesInRange(date,date),last7=minutesInRange(dayAdd(date,-6),date),s=scheduledForDate(date),p=progress(),w=currentWeek();let doneMin=sum(studyLogs(todayLog)),planMin=plannedTotal(s.blocks);let weekL=minutesInRange(weekStart(weekNo(date)),dayAdd(weekStart(weekNo(date)),6));let weekStudy=sum(studyLogs(weekL));const deadlineDays=Math.max(0,Math.ceil((parseDay(DEADLINE)-parseDay(date))/86400000));return `${pageHeading('Your personal command centre','Make progress. Keep your balance.',`${fullDate(date)} · Week ${weekNo(date)} of 10`, `<button class="btn" data-action="go-note">✎ Today’s notes</button><button class="btn btn-primary" data-action="open-log">+ Log session</button>`)}
 <div class="cards4">
 ${kpi('Studied today',duration(doneMin),`Planned: ${duration(planMin)}`,'◷')}
 ${kpi('This week',duration(weekStudy),`Week ${weekNo(date)} · Focus time`,'▦')}
 ${kpi('GRE checklist',`${p.pct}%`,`${p.done} of ${p.total} items finished`,'☑')}
 ${kpi('Deadline',`${deadlineDays} days`,'31 January 2027','◇')}
 </div>
 <div class="section-grid">
 <section class="card"><div class="card-title-row"><h2>Today’s plan</h2><button class="inline-cta" data-page="planner">Edit schedule →</button></div><div class="row-between space-bottom"><span class="pill">${esc(s.name)}</span><span class="micro muted">${duration(doneMin)} actual / ${duration(planMin)} planned</span></div><div class="progress-track space-bottom"><i style="width:${percent(doneMin,planMin)}%"></i></div>
 ${s.blocks.filter(b=>b.category!=='sleep').map(b=>`<div class="schedule-row"><span class="time-cell">${esc(b.start)}<br><span class="muted">${duration(b.minutes)}</span></span><div><div class="activity-title"><span class="cat-dot" style="background:${getCat(b.category).color}"></span><span class="schedule-name">${esc(b.label)}</span></div><p class="schedule-sub">${esc(getCat(b.category).name)}</p></div><button class="btn small" data-action="start-block" data-preset="${s.key}" data-id="${b.id}">▶</button></div>`).join('')}
 </section>
 <aside class="stack">
 <section class="card"><div class="card-title-row"><h2>Your GRE syllabus</h2><button class="inline-cta" data-page="syllabus">View checklist →</button></div>${meter('Quant',progress('quant').done,progress('quant').total,getCat('quant').color)}<div style="height:13px"></div>${meter('Verbal',progress('verbal').done,progress('verbal').total,getCat('verbal').color)}<p class="smalltext muted space-top">Tick webinars, classes and assignments individually. Progress updates automatically.</p></section>
 <section class="card"><div class="card-title-row"><h2>Week ${w.id}: what to focus on</h2><button class="inline-cta" data-page="weeks">Weekly roadmap →</button></div><p class="smalltext muted" style="line-height:1.7">${esc(w.focus)}</p><div class="separator"></div>${weekMini(w)}</section>
 <section class="card"><h2>Protect your energy</h2><p class="smalltext muted space-top" style="line-height:1.8">Your first two weeks include Python alongside GRE, IELTS and the other course. Track real hours, not just the plan. Protect your 10:30 PM–6:30 AM sleep block.</p><div class="notice warning space-top">${state.lastBackupAt?`Last backup: ${shortDate(state.lastBackupAt.slice(0,10))}.`:'No backup exported yet.'} Save a backup every week so progress does not depend on one browser.</div><button class="btn space-top" data-page="settings">Backup & privacy</button></section>
 </aside></div><div class="section-grid equal"><section class="card"><div class="card-title-row"><h2>Last 7 days</h2><button class="inline-cta" data-page="stats">Full statistics →</button></div>${dayChart(7)}</section><section class="card"><div class="card-title-row"><h2>Recently logged</h2><button class="inline-cta" data-page="log">All sessions →</button></div>${recentList(state.logs.slice().sort((a,b)=>(b.createdAt||'').localeCompare(a.createdAt||'')).slice(0,5))}</section></div>`;}
function kpi(label,num,hint,icon){return `<div class="card kpi"><span class="icon">${icon}</span><p class="kpi-label">${esc(label)}</p><p class="number font-mono">${esc(num)}</p><p class="hint">${esc(hint)}</p></div>`}
function weekMini(w){return `<div class="week-stats"><span class="pill">Quant: ${w.q.length?w.q.map(n=>'C'+n).join(', '):'Revision'}</span><span class="pill green">Verbal: ${w.v.length?w.v.map(n=>'V'+n).join(', '):'Revision'}</span></div><p class="micro muted space-top">Foundations: ${w.f.length?w.f.map(n=>'F'+n).join(', '):'Catch-up / mixed practice'}</p>`;}
function recentList(list){return list.length?list.map(l=>`<div class="schedule-row"><span class="time-cell">${esc(shortDate(l.date))}</span><div><div class="activity-title"><span class="cat-dot" style="background:${getCat(l.category).color}"></span><span class="schedule-name">${esc(l.label)}</span></div><p class="schedule-sub">${esc(getCat(l.category).name)}</p></div><strong class="micro">${duration(l.minutes)}</strong></div>`).join(''):'<div class="empty">No time logged yet. Start a timer or add a manual session.</div>'}
function dayChart(days=7,list=null){const entries=list||state.logs,dates=Array.from({length:days},(_,i)=>dayAdd(today(),i-days+1)),max=Math.max(90,...dates.map(d=>sum(studyLogs(entries.filter(x=>x.date===d)))));return `<div class="chart-days">${dates.map(d=>{let m=sum(studyLogs(entries.filter(x=>x.date===d)));return `<div class="chart-col" title="${esc(fullDate(d))}: ${duration(m)}"><div class="chart-hours">${m?hr(m/60*60)+'h':'·'}</div><div class="chart-bar-wrap"><div class="chart-bar" style="height:${Math.max(m?3:0,m/max*100)}%"></div></div><div class="chart-label">${esc(parseDay(d).toLocaleDateString(undefined,{weekday:'short'}))}</div></div>`}).join('')}</div>`}
function renderPlanner(){const tpl=state.templates[ui.template]||state.templates.morning,blocks=tpl.blocks;return `${pageHeading('Editable time blocks','Your daily schedules','Switch between the morning gym, 4 PM gym, recovery day and weekend templates. Edit duration, start times, categories and order.',`<button class="btn" data-action="preset-for-today">Use this for today</button><button class="btn btn-primary" data-action="add-block">+ Add block</button>`)}
 <div class="template-list space-bottom">${Object.entries(state.templates).map(([k,t])=>`<button class="template-chip ${k===ui.template?'selected':''}" data-action="pick-template" data-key="${k}">${esc(t.name)}</button>`).join('')}</div>
 <div class="wide-layout"><div class="stack"><section class="card"><div class="card-title-row"><div><h2>${esc(tpl.name)}</h2><p class="micro muted">${esc(tpl.description)}</p></div><div class="btn-group"><button class="btn small" data-action="rename-template">Rename</button><button class="btn small" data-action="reset-template">Reset template</button></div></div>
 <div class="notice space-bottom">Use ↑ ↓ to change block order. Changing a duration or start time automatically moves later blocks. Scheduled time is <b>not counted as completed</b> until you log it.</div>
 <div class="table-scroll"><table class="data-table edit-table"><thead><tr><th>Order</th><th>Start</th><th>Task</th><th>Category</th><th>Minutes</th><th>Actions</th></tr></thead><tbody>${blocks.map((b,i)=>`<tr><td><div class="btn-group"><button class="tiny-btn" data-action="move-block" data-dir="-1" data-id="${b.id}" ${i===0?'disabled':''} title="Move up">↑</button><button class="tiny-btn" data-action="move-block" data-dir="1" data-id="${b.id}" ${i===blocks.length-1?'disabled':''} title="Move down">↓</button></div></td><td><input class="input" type="time" aria-label="Start time for ${esc(b.label)}" data-edit-block="start" data-id="${b.id}" value="${esc(b.start)}"></td><td><input class="input" aria-label="Task name" data-edit-block="label" data-id="${b.id}" value="${esc(b.label)}"></td><td><select class="select" aria-label="Category" data-edit-block="category" data-id="${b.id}">${catOptions(b.category)}</select></td><td><input class="input" type="number" min="5" max="1440" step="5" aria-label="Duration in minutes" data-edit-block="minutes" data-id="${b.id}" value="${b.minutes}"></td><td class="table-actions"><button class="tiny-btn" data-action="start-block" data-preset="${ui.template}" data-id="${b.id}">Start</button><button class="tiny-btn red" data-action="delete-block" data-id="${b.id}">×</button></td></tr>`).join('')}</tbody></table></div></section></div>
 <aside class="stack"><section class="card"><h2>Time budget</h2><div class="separator"></div>${Object.entries(CATS).filter(([k,v])=>v.study&&blocks.some(b=>b.category===k)).map(([k,v])=>`<div class="progress-line"><span>${esc(v.name)}</span><strong>${duration(sum(blocks.filter(b=>b.category===k)))}</strong></div>`).join('')}<div class="separator"></div><div class="row-between"><strong>Total scheduled study</strong><strong>${duration(plannedTotal(blocks))}</strong></div><p class="micro muted space-top">Sleep, exercise, meals, walking and hobbies are excluded.</p></section>
 <section class="card"><h2>Assign schedules to days</h2><p class="micro muted space-top space-bottom">Your dashboard automatically uses the assigned template for each day. Wednesday starts as recovery; weekends as revision.</p>${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((name,i)=>`<div class="row-between" style="margin-bottom:11px"><label class="micro" for="day-${i}">${name}</label><select id="day-${i}" data-day-assignment="${i}" class="select" style="width:165px">${Object.entries(state.templates).map(([k,t])=>`<option value="${k}" ${state.assignment[i]===k?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div>`).join('')}</section>
 <section class="notice warning"><strong>Schedule realism:</strong> Weekend 8 AM–6 PM is a placeholder for your existing classes and singing. Edit the exact times when you know them. Don't treat that whole block as focused study by default.</section></aside></div>`}
function renderLog(){const active=state.timer;const d=ui.logDate;const list=state.logs.filter(x=>x.date===d).slice().sort((a,b)=>(b.createdAt||'').localeCompare(a.createdAt||''));const all=state.logs.slice().sort((a,b)=>b.date.localeCompare(a.date)||String(b.createdAt||'').localeCompare(String(a.createdAt||''))).slice(0,40);return `${pageHeading('Track reality, not perfection','Timer & activity log','Start a timer while studying or manually add completed minutes for any activity.',`<button class="btn btn-primary" data-action="open-log">+ Add manual entry</button>`)}
 <div class="section-grid equal"><section class="card"><div class="card-title-row"><h2>Focus timer</h2>${active?'<span class="pill green"><span class="timer-active-dot"></span> Session saved across reloads</span>':'<span class="pill gray">Ready to start</span>'}</div><div id="timerClock" class="timer-digits">00:00:00</div>
 <div class="field-grid space-bottom"><div class="field"><label class="form-label" for="timerCategory">Category</label><select class="select" id="timerCategory" ${active?'disabled':''}>${catOptions(active?.category||'quant')}</select></div><div class="field"><label class="form-label" for="timerTask">Task name</label><input id="timerTask" class="input" value="${esc(active?.label||'GRE study session')}" ${active?'disabled':''}></div></div>
 <div class="field space-bottom"><label class="form-label" for="timerTopic">Link to a GRE checklist item (optional)</label><select class="select" id="timerTopic" ${active?'disabled':''}>${syllabusSelect(active?.itemId||'')}</select></div>
 <div class="timer-controls">${!active?'<button class="btn btn-primary" data-action="timer-start">▶ Start focus timer</button>':`<button class="btn" data-action="timer-toggle">${active.running?'Ⅱ Pause':'▶ Resume'}</button><button class="btn btn-primary" data-action="timer-finish">■ Stop & save time</button><button class="btn btn-red" data-action="timer-discard">Discard</button>`}</div><p class="micro muted space-top">You can switch pages while the timer runs. It uses the clock rather than relying on an open browser tab.</p></section>
 <section class="card"><div class="card-title-row"><h2>Activity for a specific day</h2><input type="date" id="logDate" class="input" style="width:156px" value="${d}" data-action="log-date"></div>
 <div class="row-between"><span class="muted smalltext">Logged study time</span><strong>${duration(sum(studyLogs(list)))}</strong></div><div class="separator"></div>${list.length?list.map(l=>`<div class="schedule-row"><span class="time-cell">${duration(l.minutes)}</span><div><div class="activity-title"><span class="cat-dot" style="background:${getCat(l.category).color}"></span><span class="schedule-name">${esc(l.label)}</span></div><p class="schedule-sub">${esc(getCat(l.category).name)}${l.itemId?' · '+esc(syllabusItem(l.itemId)?.code||'GRE'):''}</p></div><div class="btn-group"><button class="tiny-btn" data-action="edit-entry" data-id="${l.id}">Edit</button><button class="tiny-btn red" data-action="delete-entry" data-id="${l.id}">×</button></div></div>`).join(''):'<p class="empty">No activities logged for this date.</p>'}</section></div>
 <section class="card space-top"><div class="card-title-row"><h2>Recent activity</h2><span class="micro muted">Newest 40 entries · Edit or delete mistakes</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Date</th><th>Category</th><th>Task</th><th>Duration</th><th></th></tr></thead><tbody>${all.map(l=>`<tr><td>${esc(shortDate(l.date))}</td><td>${esc(getCat(l.category).name)}</td><td>${esc(l.label)}</td><td><strong>${duration(l.minutes)}</strong></td><td class="table-actions"><button class="tiny-btn" data-action="edit-entry" data-id="${l.id}">Edit</button><button class="tiny-btn red" data-action="delete-entry" data-id="${l.id}">Delete</button></td></tr>`).join('')||'<tr><td colspan="5" class="muted">No entries yet.</td></tr>'}</tbody></table></div></section>`;}
function syllabusSelect(selected){return `<option value="">None</option>`+state.syllabus.map(it=>`<option value="${it.id}" ${it.id===selected?'selected':''}>${esc(it.code)} · ${esc(it.title.slice(0,52))}</option>`).join('')}
function renderSyllabus(){const p=progress(),qp=progress('quant'),vp=progress('verbal');const groups=[{subject:'quant',stage:'foundation',title:'17 Quant foundation webinars',sub:'Durations account for approximately 2× video time for pausing and note-taking.'},{subject:'quant',stage:'in',title:'13 Quant in-class sessions',sub:'Each 2-hour recording is budgeted as 4 hours including notes.'},{subject:'quant',stage:'post',title:'13 Quant post-class assignments',sub:'Default 2.5 hours each; edit the estimate to match each assignment.'},{subject:'verbal',stage:'pre',title:'12 Verbal pre-class tasks',sub:'Approximately 30 minutes per class.'},{subject:'verbal',stage:'in',title:'12 Verbal in-class sessions',sub:'Estimated 4.5 hours per session including notes. Rename topics after class.'},{subject:'verbal',stage:'post',title:'12 Verbal post-class assignments',sub:'Approximately 35 minutes per session.'}];return `${pageHeading('One checkbox at a time','GRE syllabus tracker','All 79 components are listed separately. Mark completed items, add subject notes and edit any duration estimate.',`<button class="btn" data-action="open-log">+ Log study hours</button>`)}
 <div class="cards4 space-bottom">${kpi('Total progress',`${p.pct}%`,`${p.done} / ${p.total} checklist items`,'✓')}${kpi('Quant',`${qp.pct}%`,`${qp.done} / ${qp.total} components`,'∑')}${kpi('Verbal',`${vp.pct}%`,`${vp.done} / ${vp.total} components`,'A')}${kpi('Estimated work',duration(p.planned),`${duration(p.worked)} worth checked off`,'◷')}</div>
 <div class="card"><div class="row-between space-bottom" style="flex-wrap:wrap"><div class="segmented"><button data-action="syllabus-filter" data-filter="subject" data-val="all" class="${ui.syllabusSubject==='all'?'active':''}">All</button><button data-action="syllabus-filter" data-filter="subject" data-val="quant" class="${ui.syllabusSubject==='quant'?'active':''}">Quant</button><button data-action="syllabus-filter" data-filter="subject" data-val="verbal" class="${ui.syllabusSubject==='verbal'?'active':''}">Verbal</button></div><select class="select" style="width:180px" id="stageFilter"><option value="all">All task types</option>${['foundation','pre','in','post'].map(s=>`<option value="${s}" ${s===ui.syllabusStage?'selected':''}>${stageLabel(s)}</option>`).join('')}</select><input class="input" style="max-width:260px" placeholder="Search a topic…" id="syllabusSearch" value="${esc(ui.syllabusSearch)}"></div>
 ${groups.filter(g=>ui.syllabusSubject==='all'||ui.syllabusSubject===g.subject).filter(g=>ui.syllabusStage==='all'||ui.syllabusStage===g.stage).map(g=>{let all=state.syllabus.filter(x=>x.subject===g.subject&&x.stage===g.stage),list=all.filter(x=>(x.title+' '+x.code).toLowerCase().includes(ui.syllabusSearch.toLowerCase()));return `<section class="syllabus-group"><div class="syllabus-head"><div><h3>${esc(g.title)}</h3><p class="micro muted">${esc(g.sub)}</p></div><span class="pill ${all.every(x=>x.completed)?'green':''}">${all.filter(x=>x.completed).length}/${all.length} done</span></div>${list.map(x=>`<div class="syllabus-item ${x.completed?'complete':''}"><input type="checkbox" aria-label="Mark ${esc(x.code)} complete" data-syllabus-check="${x.id}" ${x.completed?'checked':''}><div><div class="syllabus-name"><span class="chapter-code">${esc(x.code)}</span>${esc(x.title)}</div><p class="syllabus-meta">${esc(stageLabel(x.stage))} · estimated ${duration(x.minutes)}${x.note?' · Has topic notes':''}</p></div><div class="syllabus-action"><button class="tiny-btn" data-action="edit-syllabus" data-id="${x.id}">Notes / edit</button><button class="tiny-btn" data-action="start-syllabus" data-id="${x.id}">▶</button></div></div>`).join('')||'<p class="empty">No matching items.</p>'}</section>`}).join('')}</div>`;}

function weekWorkload(w){
 const ids=[...w.q.flatMap(n=>['q'+n,'qp'+n]),...w.v.flatMap(n=>['vp'+n,'v'+n,'vpost'+n]),...w.f.map(n=>'f'+n)];
 return ids.reduce((acc,id)=>acc+(syllabusItem(id)?.minutes||0),0);
}
function weekDoneCount(w){const ids=[...w.q.flatMap(n=>['q'+n,'qp'+n]),...w.v.flatMap(n=>['vp'+n,'v'+n,'vpost'+n]),...w.f.map(n=>'f'+n)];return {done:ids.filter(id=>syllabusItem(id)?.completed).length,total:ids.length}}
function renderWeeks(){const selected=state.weeks[ui.week-1]||state.weeks[0];const st=weekStart(selected.id),end=dayAdd(st,6),logged=minutesInRange(st,end);
 const grade=weekDoneCount(selected),actualQ=minutesFor(logged,'quant'),actualV=minutesFor(logged,'verbal'),actualI=minutesFor(logged,'ielts'),actualC=minutesFor(logged,'career'),actualP=minutesFor(logged,'python');
 const row=(label,actual,goal,key)=>`<div class="goal-row"><div class="row-between"><label class="smalltext">${label}</label><span class="micro muted">${duration(actual)} logged / ${Number(goal).toFixed(1)}h target</span></div><div class="progress-track"><i style="width:${percent(actual,goal*60)}%"></i></div><div class="goal-field">Target hours <input class="input" type="number" min="0" max="80" step="0.25" data-goal="${key}" value="${Number(goal)}"></div></div>`;
 const planItems=(subject,nums)=>nums.map(n=>{let id=(subject==='quant'?'q':'v')+n,s=syllabusItem(id),parts=subject==='quant'?['q'+n,'qp'+n]:['vp'+n,'v'+n,'vpost'+n];let all=parts.every(k=>syllabusItem(k)?.completed);return `<div class="week-step"><input type="checkbox" data-bundle-check="${subject}:${n}" ${all?'checked':''} title="Mark all related tasks complete"><div><strong>${subject==='quant'?'Quant C':'Verbal V'}${n}</strong><p class="micro muted">${esc(s?.title||'Class')} · ${parts.filter(k=>syllabusItem(k)?.completed).length}/${parts.length} tasks done</p></div></div>`}).join('')||'<p class="micro muted">Revision / catch-up: no new class assigned.</p>';
 return `${pageHeading('10 weeks · 23 Nov to 31 Jan','Your alternating weekly roadmap','Odd study weeks emphasize Quant; even study weeks emphasize Verbal. Rearrange classes and weekly hour targets whenever necessary.',`<button class="btn" data-action="go-current-week">Current week</button>`)}
 <div class="wide-layout"><div class="stack"><section class="card"><h2>Choose a week</h2><div class="week-plan-list">${state.weeks.map(w=>{let x=weekDoneCount(w);return `<button class="week-plan-row ${ui.week===w.id?'selected':''}" data-action="pick-week" data-week="${w.id}"><span class="week-title"><strong>Week ${w.id}</strong><span class="micro muted">${monthDay(weekStart(w.id))}–${monthDay(dayAdd(weekStart(w.id),6))}</span></span><span class="week-topics"><b>${w.q.length} Quant</b> · ${w.v.length} Verbal · ${w.f.length} webinars</span><span class="micro muted">${x.done}/${x.total} tasks</span><span class="week-arrow">›</span></button>`}).join('')}</div></section>
 <section class="card"><div class="card-title-row"><div><span class="pill">Week ${selected.id} · ${monthDay(st)}–${monthDay(end)}</span><h2 class="space-top">${selected.id===10?'Revision and mocks':selected.id%2===1?'Quant-focus week':'Verbal-focus week'}</h2></div><button class="btn small" data-action="edit-week">Edit classes</button></div>
 <p class="smalltext muted space-top">${esc(selected.focus)}</p>
 <div class="notice space-top ${weekWorkload(selected)>21.25*60?'warning':''}"><b>Estimated GRE syllabus load: ${duration(weekWorkload(selected))}</b> across the assigned webinars, classes and prep / post-class tasks. Weekday GRE capacity is about 21h 15m. ${weekWorkload(selected)>21.25*60?'This week may be overloaded. Move a webinar forward or a task to a lighter week; weekend nights are intended for revision.':'Leave any unallocated time for review, catch-up and breaks.'}</div>
 <div class="section-grid equal space-top"><div><h3>Quant classes</h3>${planItems('quant',selected.q)}</div><div><h3>Verbal classes</h3>${planItems('verbal',selected.v)}</div></div>
 <h3 class="space-top">Foundation webinars to finish before class</h3><div class="week-plan-foundations">${selected.f.map(n=>{let s=syllabusItem('f'+n);return `<div class="week-step"><input type="checkbox" data-syllabus-check="f${n}" ${s?.completed?'checked':''}><div><strong>F${n} · ${esc(s?.title||'Webinar')}</strong><p class="micro muted">${duration(s?.minutes||0)} estimated with notes</p></div></div>`}).join('')||'<p class="micro muted">No new webinars; revise foundation weaknesses.</p>'}</div>
 <div class="field space-top"><label class="form-label" for="weekFocus">Weekly focus / adjustments</label><textarea class="textarea" id="weekFocus" rows="3" placeholder="What needs more time this week?">${esc(selected.focus)}</textarea></div>
 <div class="field space-top"><label class="form-label" for="weekNote">Weekly review and backlog notes</label><textarea class="textarea" id="weekNote" rows="4" placeholder="What worked? What can move to next week?">${esc(selected.note||'')}</textarea></div></section></div>
 <aside class="stack"><section class="card"><h2>Study hours this week</h2><p class="micro muted space-bottom">Targets are adjustable. Hours are counted only when logged, not when planned.</p>${row('GRE Quant',actualQ,selected.goalQ,'goalQ')}${row('GRE Verbal',actualV,selected.goalV,'goalV')}${row('IELTS',actualI,selected.goalIELTS,'goalIELTS')}${row('Career course',actualC,selected.goalCareer,'goalCareer')}${row('Python',actualP,selected.goalPython,'goalPython')}</section>
 <section class="card"><h2>Burnout protection check</h2><p class="micro muted space-top space-bottom">Check these during the Sunday evening review. They are reminders, not a productivity score.</p>${CHECKS.map((ch,i)=>`<label class="week-check"><input type="checkbox" data-week-check="${i}" ${selected.checks?.[i]?'checked':''}><span>${esc(ch)}</span></label>`).join('')}</section>
 <section class="notice"><strong>A practical adjustment rule:</strong> If you miss a Quant assignment, shift its estimated time into the next available weekday GRE block. Do not borrow from sleep or automatically double the next day.</section></aside></div>`;
}
function noteEntry(date){return state.notes[date]||{text:'',priority:'',win:'',mood:3};}
function renderNotes(){const n=noteEntry(ui.noteDate);const dlogs=minutesInRange(ui.noteDate,ui.noteDate);return `${pageHeading('Private journal','Your daily notes','Write freely, note what you learned, and record one next step. Saved locally on this device.',`<button class="btn" data-action="note-today">Jump to today</button>`)}
 <div class="wide-layout"><div class="stack"><section class="card"><div class="card-title-row"><h2>${esc(fullDate(ui.noteDate))}</h2><input class="input" type="date" id="noteDate" value="${ui.noteDate}" style="max-width:165px"></div>
 <div class="field space-top"><label class="form-label" for="dailyPriority">Main priority for this day</label><input class="input" id="dailyPriority" value="${esc(n.priority)}" placeholder="e.g. Finish statistics webinar + 30 reading questions"></div>
 <div class="field space-top"><label class="form-label" for="dailyText">Study notes, mistakes and reminders</label><textarea class="textarea" id="dailyText" style="min-height:280px" placeholder="What did you study? Which questions need another attempt? What helped today?">${esc(n.text)}</textarea></div>
 <div class="field space-top"><label class="form-label" for="dailyWin">One thing that went well</label><input class="input" id="dailyWin" value="${esc(n.win)}" placeholder="Even a small win counts"></div>
 <div class="space-top"><label class="form-label">Energy check-in · ${n.mood||3}/5</label><div class="mood-buttons">${[1,2,3,4,5].map(x=>`<button data-action="set-mood" data-mood="${x}" class="${Number(n.mood||3)===x?'active':''}">${x}</button>`).join('')}</div><p class="micro muted space-top">1 = very tired, 5 = energized. This is only for your personal reflection.</p></div>
 <div class="notice success space-top">Changes save automatically while you type. Use Settings to export a backup every week.</div></section></div>
 <aside class="stack"><section class="card"><h2>Activity on this day</h2><div class="separator"></div><p class="smalltext"><strong>${duration(sum(studyLogs(dlogs)))}</strong> of logged study</p>${dlogs.map(l=>`<div class="progress-line"><span>${esc(l.label)}</span><strong>${duration(l.minutes)}</strong></div>`).join('')||'<p class="micro muted space-top">Nothing logged yet.</p>'}<button class="btn small space-top" data-action="log-note-date">+ Log time for this date</button></section>
 <section class="card"><h2>Keep it simple</h2><p class="smalltext muted space-top" style="line-height:1.8">Daily notes do not need to be essays. Try one sentence about progress, one mistake worth revisiting, and one priority for tomorrow.</p></section></aside></div>`;
}
function renderStats(){const days=ui.statsRange==='all'?null:Math.max(1,Number(ui.statsRange)||7),to=today(),from=days?dayAdd(to,-days+1):START,logs=minutesInRange(from,to),st=studyLogs(logs),total=sum(st),allMinutes=sum(logs),activeDays=new Set(st.map(l=>l.date)).size,elapsedDays=days||Math.max(1,Math.round((parseDay(to)-parseDay(START))/86400000)+1),avg=total/Math.max(1,elapsedDays),p=progress();
 const chartDays=days?Math.min(30,days):30;const categories=Object.entries(CATS).map(([id,data])=>({id,...data,minutes:minutesFor(logs,id)})).filter(x=>x.minutes>0).sort((a,b)=>b.minutes-a.minutes);
 const q=categories.find(x=>x.id==='quant')?.minutes||0,v=categories.find(x=>x.id==='verbal')?.minutes||0;
 return `${pageHeading('Progress you can measure','Your study statistics','Every chart uses your actual logged time. Editing or deleting a log updates all results.',`<button class="btn" data-page="log">View activity log</button>`)}
 <div class="tabbar space-bottom">${[['7','Last 7 days'],['14','Last 14 days'],['30','Last 30 days'],['all','All time']].map(([k,label])=>`<button class="tab ${ui.statsRange===k?'active':''}" data-action="stats-range" data-val="${k}">${label}</button>`).join('')}</div>
 <div class="cards4 space-bottom">${kpi('Total focused study',duration(total),'Across selected time range','◷')}${kpi('Daily average',duration(avg),`${elapsedDays} calendar days in range`,'▦')}${kpi('Days with study',String(activeDays),`Of ${elapsedDays} calendar days`,'✓')}${kpi('Other activities',duration(allMinutes-total),'Exercise, hobbies, meals, etc.','◇')}</div>
 <div class="section-grid equal"><section class="card"><h2>Study hours by day</h2><p class="micro muted space-top space-bottom">Most recent ${chartDays} days</p>${dayChart(chartDays)}</section><section class="card"><h2>Where your time went</h2><p class="micro muted space-top space-bottom">Includes everything you have chosen to log</p>${categories.length?categories.map(x=>`<div class="category-bar"><div class="row-between"><span class="smalltext"><i class="cat-dot" style="background:${x.color};display:inline-block;margin-right:8px"></i>${esc(x.name)}</span><b>${duration(x.minutes)}</b></div><div class="progress-track"><i style="width:${percent(x.minutes,allMinutes)}%;background:${x.color}"></i></div></div>`).join(''):'<p class="empty">No activity yet. Start the timer or add hours manually to build your dashboard.</p>'}</section></div>
 <div class="section-grid equal space-top"><section class="card"><h2>GRE work completed</h2><div class="row-between space-top space-bottom"><strong>${p.pct}% complete</strong><span class="smalltext muted">${p.done} / ${p.total} tasks</span></div><div class="progress-track"><i style="width:${p.pct}%"></i></div><div class="separator"></div>${meter('Quant items',progress('quant').done,progress('quant').total,getCat('quant').color)}<div style="height:12px"></div>${meter('Verbal items',progress('verbal').done,progress('verbal').total,getCat('verbal').color)}<div class="separator"></div><div class="progress-line"><span>Estimated syllabus time remaining</span><strong>${duration(p.planned-p.worked)}</strong></div><p class="micro muted space-top">Checklist estimates are not actual logged time; the two measurements are independent.</p></section>
 <section class="card"><h2>Study balance</h2><div class="separator"></div><div class="progress-line"><span>Quant logged</span><strong>${duration(q)}</strong></div><div class="progress-line"><span>Verbal logged</span><strong>${duration(v)}</strong></div><div class="progress-line"><span>GRE combined</span><strong>${duration(q+v)}</strong></div><div class="progress-line"><span>IELTS</span><strong>${duration(minutesFor(logs,'ielts'))}</strong></div><div class="progress-line"><span>Python</span><strong>${duration(minutesFor(logs,'python'))}</strong></div><div class="progress-line"><span>Career course</span><strong>${duration(minutesFor(logs,'career'))}</strong></div><div class="notice space-top">Avoid chasing the total hours alone. Finishing lessons, correctly solving problems and getting adequate rest matter more than an artificially high timer number.</div></section></div>`;
}
function renderSettings(){return `${pageHeading('Your data stays yours','Settings & backups','Everything works without a login or cloud account. Browser storage is convenient, but backups are essential.')}
 <div class="wide-layout"><div class="stack"><section class="card settings-group"><h2>Data privacy & recovery</h2><p>Your study logs, notes, checklist and schedules are saved automatically to browser storage on this device. The app has no analytics, trackers, external libraries or server connection.</p><div class="notice warning space-top"><b>Important:</b> Data is not automatically synchronized across devices. Private browsing, clearing site data, changing browsers or losing this device can erase the local copy. Export a backup weekly and save it somewhere secure.</div>
 <div class="field-grid space-top"><button class="btn btn-primary" data-action="export-json">Download full backup (.json)</button><button class="btn" data-action="export-encrypted">Encrypted backup (password)</button><button class="btn" data-action="export-csv">Export time logs (.csv)</button><button class="btn" data-action="import-open">Restore a backup</button></div><input id="backupFile" type="file" accept=".json,.focusbackup,application/json" class="hidden" />
 <p class="micro muted space-top">${state.lastBackupAt?'Last export: '+new Date(state.lastBackupAt).toLocaleString():'No backup has been exported yet.'} Encrypted backups use AES-GCM with a password-derived key; remember that password, as the app cannot recover it.</p></section>
 <section class="card settings-group"><h2>Daily study target</h2><p>Used for your personal reference; it never overwrites your logged time.</p><div class="field space-top" style="max-width:240px"><label class="form-label">Study target (hours per weekday)</label><input class="input" id="dailyTarget" type="number" min="1" max="16" step="0.25" value="${(state.settings.dailyGoal/60).toFixed(2)}"></div></section></div>
 <aside class="stack"><section class="card"><h2>Workspace details</h2><div class="progress-line"><span>Study logs</span><strong>${state.logs.length}</strong></div><div class="progress-line"><span>Journal days</span><strong>${Object.keys(state.notes).length}</strong></div><div class="progress-line"><span>GRE checklist items</span><strong>${state.syllabus.length}</strong></div><div class="progress-line"><span>Schedules</span><strong>${Object.keys(state.templates).length}</strong></div><div class="progress-line"><span>First created</span><strong>${shortDate(state.createdAt.slice(0,10))}</strong></div></section>
 <section class="card danger-zone"><h2>Reset workspace</h2><p class="smalltext muted space-top space-bottom">Starts over with default schedules, an unchecked GRE syllabus and no logs or notes. This cannot be undone without a backup.</p><button class="btn btn-red" data-action="reset-workspace">Erase local workspace</button></section><section class="notice">Tip: You can download the whole app and open it offline. To use it on more than one device, transfer your exported backup and import it on the other device.</section></aside></div>`}
function twoDigits(n){return String(Math.max(0,Math.floor(n))).padStart(2,'0')}
function timerElapsed(){const t=state?.timer;if(!t)return 0;return (Number(t.elapsedMs)||0)+(t.running&&t.startedAt?Math.max(0,Date.now()-t.startedAt):0)}
function refreshTimerDisplay(){const el=$('#timerClock');if(!el)return;const sec=Math.floor(timerElapsed()/1000);el.textContent=`${twoDigits(sec/3600)}:${twoDigits((sec%3600)/60)}:${twoDigits(sec%60)}`;}
function beginTimer(cat,label,itemId=''){if(state.timer){toast('Finish or discard your current timer first.');navigate('log');return;}state.timer={category:cat,label:label||'Focus session',itemId:itemId||'',date:today(),running:true,startedAt:Date.now(),elapsedMs:0};persist();navigate('log');toast('Timer started. You can navigate away and return later.');}
function toggleTimer(){const t=state.timer;if(!t)return;if(t.running){t.elapsedMs=timerElapsed();t.startedAt=null;t.running=false}else{t.startedAt=Date.now();t.running=true}persist();render();}
function finishTimer(){const t=state.timer;if(!t)return;let minutes=Math.round(timerElapsed()/60000);if(minutes<1){toast('The timer has not reached one minute yet.');return;}state.logs.push({id:uid(),date:t.date||today(),label:t.label,category:t.category,minutes,itemId:t.itemId||'',source:'timer',createdAt:new Date().toISOString()});state.timer=null;persist();render();toast(`${duration(minutes)} saved to your activity log.`);}
function switchDateTemplate(key){if(!state.templates[key])return;state.dateAssignments=state.dateAssignments||{};state.dateAssignments[today()]=key;persist();render();}
function reflow(blocks,from=1){for(let i=Math.max(1,from);i<blocks.length;i++){const prev=blocks[i-1];blocks[i].start=toClock(toMinutes(prev.start)+Math.max(5,Number(prev.minutes)||5));}}
function modal(content){$('#modalRoot').innerHTML=`<div class="modal-overlay" id="modalOverlay"><div class="modal" role="dialog" aria-modal="true">${content}</div></div>`;$('#modalOverlay').addEventListener('click',e=>{if(e.target.id==='modalOverlay')closeModal()});}
function closeModal(){$('#modalRoot').innerHTML='';}
function logModal(id=null,overrides={}){const x=state.logs.find(y=>y.id===id)||{date:overrides.date||ui.logDate||today(),label:overrides.label||'',category:overrides.category||'quant',minutes:60,itemId:overrides.itemId||''};modal(`<form id="manualLogForm"><h2>${id?'Edit a logged session':'Log an activity manually'}</h2><p class="micro muted space-bottom">Only completed time is saved. Every category can be tracked, not just study.</p>
 <div class="field-grid"><div class="field"><label class="form-label">Date</label><input class="input" type="date" name="date" value="${esc(x.date)}" required></div><div class="field"><label class="form-label">Category</label><select class="select" name="category">${catOptions(x.category)}</select></div></div>
 <div class="field"><label class="form-label">Activity name</label><input class="input" name="label" value="${esc(x.label)}" placeholder="e.g. Probability webinar notes" required maxlength="200"></div>
 <div class="field-grid"><div class="field"><label class="form-label">Hours</label><input class="input" name="hours" type="number" value="${Math.floor(x.minutes/60)}" min="0" max="24" required></div><div class="field"><label class="form-label">Minutes</label><input class="input" name="minutes" type="number" value="${x.minutes%60}" min="0" max="59" required></div></div>
 <div class="field"><label class="form-label">Related GRE task (optional)</label><select class="select" name="itemId">${syllabusSelect(x.itemId)}</select></div>
 <div class="modal-actions"><button type="button" class="btn" data-action="modal-close">Cancel</button><button type="submit" class="btn btn-primary">${id?'Save changes':'Add activity'}</button></div><input type="hidden" name="id" value="${id||''}"></form>`);}
function syllabusModal(id){const x=syllabusItem(id);if(!x)return;modal(`<form id="syllabusForm"><h2>GRE task details</h2><p class="micro muted space-bottom">${esc(x.code)} · ${esc(stageLabel(x.stage))}</p><div class="field"><label class="form-label">Topic / class name</label><input class="input" name="title" value="${esc(x.title)}" required></div><div class="field"><label class="form-label">Estimated total minutes, including note-making</label><input class="input" type="number" name="minutes" min="5" max="2000" value="${x.minutes}" required></div><div class="field"><label class="form-label">Your notes for this topic</label><textarea class="textarea" name="note" rows="6" placeholder="Key concepts, tricky problems, formulas or revision points">${esc(x.note)}</textarea></div><label class="week-check"><input type="checkbox" name="completed" ${x.completed?'checked':''}> Mark task complete</label><div class="modal-actions"><button type="button" class="btn" data-action="modal-close">Cancel</button><button class="btn btn-primary" type="submit">Save topic</button></div><input type="hidden" name="id" value="${x.id}"></form>`);}
function weekModal(){const w=state.weeks[ui.week-1];const options=(subject,selected)=>Array.from({length:subject==='quant'?13:subject==='verbal'?12:17},(_,i)=>{let n=i+1,it=syllabusItem((subject==='quant'?'q':subject==='verbal'?'v':'f')+n);return `<label class="week-check"><input type="checkbox" name="${subject}" value="${n}" ${selected.includes(n)?'checked':''}><span><b>${subject==='quant'?'C':subject==='verbal'?'V':'F'}${n}</b> ${esc(it?.title||'')}</span></label>`}).join('');
 modal(`<form id="weekForm"><h2>Edit Week ${w.id}</h2><p class="micro muted space-bottom">Reassign classes or webinars. Assigning an item here removes it from any other week to prevent duplicates.</p><div class="field"><label class="form-label">Quant classes</label><div class="scroll-choices">${options('quant',w.q)}</div></div><div class="field"><label class="form-label">Verbal classes</label><div class="scroll-choices">${options('verbal',w.v)}</div></div><div class="field"><label class="form-label">Foundation webinars</label><div class="scroll-choices">${options('foundation',w.f)}</div></div><div class="modal-actions"><button type="button" class="btn" data-action="modal-close">Cancel</button><button class="btn btn-primary" type="submit">Save week arrangement</button></div></form>`);}
function downloadFile(filename,content,type='application/octet-stream'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function markBackup(){state.lastBackupAt=new Date().toISOString();persist();render();}
function exportJSON(){const data=JSON.stringify({...state,lastBackupAt:new Date().toISOString()},null,2);downloadFile(`focus-atlas-backup-${today()}.json`,data,'application/json');markBackup();toast('Full backup downloaded. Store it somewhere secure.');}
function exportCSV(){const cols=['date','category','label','minutes','hours','gre_task','source'];const quote=v=>'"'+String(v??'').replaceAll('"','""')+'"';const lines=[cols.join(','),...state.logs.map(l=>[l.date,getCat(l.category).name,l.label,l.minutes,(l.minutes/60).toFixed(2),l.itemId||'',l.source||'manual'].map(quote).join(','))].join('\r\n');downloadFile(`focus-atlas-time-logs-${today()}.csv`,'\uFEFF'+lines,'text/csv;charset=utf-8');toast('CSV export downloaded.');}
const toB64=u8=>btoa(Array.from(u8,c=>String.fromCharCode(c)).join(''));
const fromB64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function encryptBackup(password){if(!crypto?.subtle)throw Error('Encrypted backup requires a secure browser context.');const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12));const passKey=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);const key=await crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:250000,hash:'SHA-256'},passKey,{name:'AES-GCM',length:256},false,['encrypt']);const content=JSON.stringify({...state,lastBackupAt:new Date().toISOString()});const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(content));return JSON.stringify({app:'Focus Atlas',format:'aes-256-gcm-pbkdf2',version:1,salt:toB64(salt),iv:toB64(iv),ciphertext:toB64(new Uint8Array(cipher))},null,2);}
async function decryptBackup(blob,password){const salt=fromB64(blob.salt),iv=fromB64(blob.iv),cipher=fromB64(blob.ciphertext);const p=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);const key=await crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:250000,hash:'SHA-256'},p,{name:'AES-GCM',length:256},false,['decrypt']);return JSON.parse(new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv},key,cipher)));}
async function importBackup(file){if(!file)return;try{const raw=JSON.parse(await file.text());let data=raw;if(raw.format==='aes-256-gcm-pbkdf2'){const password=prompt('Password for this encrypted Focus Atlas backup:');if(password===null)return;data=await decryptBackup(raw,password);}const loaded=hydrate(data);if(!confirm('Replace your current workspace with the selected backup? Export your current data first if you want to keep it.'))return;state=loaded;persist();render();toast('Backup restored successfully.');}catch(e){alert('Backup could not be restored. File may be invalid or the password incorrect.\n'+e.message);}}
function handleClick(e){const nav=e.target.closest('[data-page]');if(nav){navigate(nav.dataset.page);return;}const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;
 switch(a){
 case 'open-log':logModal(null,{date:ui.page==='notes'?ui.noteDate:ui.page==='log'?ui.logDate:today()});break;
 case 'log-note-date':logModal(null,{date:ui.noteDate});break;
 case 'edit-entry':logModal(id);break;
 case 'delete-entry':if(confirm('Delete this time entry?')){state.logs=state.logs.filter(x=>x.id!==id);persist();render();}break;
 case 'modal-close':closeModal();break;
 case 'go-note':ui.noteDate=today();navigate('notes');break;
 case 'note-today':ui.noteDate=today();render();break;
 case 'pick-template':ui.template=el.dataset.key;render();break;
 case 'preset-for-today':switchDateTemplate(ui.template);toast('Today is now assigned to this schedule.');break;
 case 'add-block':{const blocks=state.templates[ui.template].blocks,insert=blocks.findIndex(b=>b.category==='sleep');let i=insert<0?blocks.length:insert;const before=blocks[i-1];const b=block('New activity','other',before?toClock(toMinutes(before.start)+before.minutes):'07:00',30);blocks.splice(i,0,b);reflow(blocks,i+1);persist();render();break;}
 case 'move-block':{const blocks=state.templates[ui.template].blocks,i=blocks.findIndex(b=>b.id===id),j=i+Number(el.dataset.dir);if(i<0||j<0||j>=blocks.length)return;const begin=blocks[0].start;[blocks[i],blocks[j]]=[blocks[j],blocks[i]];blocks[0].start=begin;reflow(blocks,1);persist();render();break;}
 case 'delete-block':{const blocks=state.templates[ui.template].blocks,i=blocks.findIndex(b=>b.id===id);if(i<0)return;if(!confirm('Remove this block from the '+state.templates[ui.template].name+' schedule?'))return;blocks.splice(i,1);reflow(blocks,Math.max(1,i));persist();render();break;}
 case 'rename-template':{let name=prompt('New schedule name:',state.templates[ui.template].name);if(name&&name.trim()){state.templates[ui.template].name=name.trim().slice(0,60);persist();render();}break;}
 case 'reset-template':if(confirm('Reset this schedule to its original times and activities?')){state.templates[ui.template]=makeTemplates()[ui.template];persist();render();}break;
 case 'start-block':{let t=state.templates[el.dataset.preset]||state.templates.morning,b=t.blocks.find(x=>x.id===id);if(b)beginTimer(b.category,b.label);break;}
 case 'timer-start':beginTimer($('#timerCategory').value,$('#timerTask').value.trim()||'Focus session',$('#timerTopic').value);break;
 case 'timer-toggle':toggleTimer();break;
 case 'timer-finish':finishTimer();break;
 case 'timer-discard':if(confirm('Discard the running or paused session without logging it?')){state.timer=null;persist();render();}break;
 case 'syllabus-filter':ui[el.dataset.filter==='subject'?'syllabusSubject':'syllabusStage']=el.dataset.val;render();break;
 case 'edit-syllabus':syllabusModal(id);break;
 case 'start-syllabus':{let s=syllabusItem(id);if(s)beginTimer(s.subject,s.title,id);break;}
 case 'pick-week':ui.week=Number(el.dataset.week);render();break;
 case 'go-current-week':ui.week=weekNo(today());render();break;
 case 'edit-week':weekModal();break;
 case 'set-mood':noteEntryMutable(ui.noteDate).mood=Number(el.dataset.mood);persist();render();break;
 case 'stats-range':ui.statsRange=el.dataset.val;render();break;
 case 'export-json':exportJSON();break;
 case 'export-csv':exportCSV();break;
 case 'export-encrypted':{const pass=prompt('Choose a strong password for your encrypted backup. You must remember it:');if(pass===null)return;if(pass.length<10){alert('Use at least 10 characters for your backup password.');return;}const again=prompt('Repeat your backup password:');if(again!==pass){alert('Passwords did not match.');return;}encryptBackup(pass).then(content=>{downloadFile(`focus-atlas-encrypted-${today()}.focusbackup`,content,'application/json');markBackup();toast('Encrypted backup downloaded.');}).catch(err=>alert(err.message));break;}
 case 'import-open':$('#backupFile')?.click();break;
 case 'reset-workspace':if(confirm('This deletes all your logs, notes and GRE progress from this device. Continue?')&&confirm('Last confirmation: Have you exported a backup?')){state=freshState();persist();navigate('dashboard');toast('Workspace reset.');}break;
 }
}
function noteEntryMutable(date){if(!state.notes[date])state.notes[date]={text:'',priority:'',win:'',mood:3};return state.notes[date]}
function handleChange(e){const t=e.target;
 if(t.id==='backupFile'){importBackup(t.files[0]);t.value='';return;}
 if(t.dataset.syllabusCheck){const x=syllabusItem(t.dataset.syllabusCheck);if(x){x.completed=t.checked;x.completedAt=t.checked?new Date().toISOString():null;persist();render();}return;}
 if(t.dataset.bundleCheck){let [sub,n]=t.dataset.bundleCheck.split(':'),ids=sub==='quant'?['q'+n,'qp'+n]:['vp'+n,'v'+n,'vpost'+n];ids.forEach(id=>{const x=syllabusItem(id);if(x){x.completed=t.checked;x.completedAt=t.checked?new Date().toISOString():null}});persist();render();return;}
 if(t.dataset.weekCheck!==undefined){state.weeks[ui.week-1].checks[t.dataset.weekCheck]=t.checked;persist();return;}
 if(t.dataset.goal){state.weeks[ui.week-1][t.dataset.goal]=Math.min(80,Math.max(0,Number(t.value)||0));persist();render();return;}
 if(t.dataset.dayAssignment!==undefined){state.assignment[Number(t.dataset.dayAssignment)]=t.value;persist();render();return;}
 if(t.dataset.editBlock){const b=state.templates[ui.template].blocks.find(x=>x.id===t.dataset.id);if(!b)return;const blocks=state.templates[ui.template].blocks,i=blocks.indexOf(b);if(t.dataset.editBlock==='minutes'){b.minutes=Math.max(5,Math.min(1440,Number(t.value)||5));reflow(blocks,i+1)}else if(t.dataset.editBlock==='start'){b.start=t.value||b.start;reflow(blocks,i+1)}else{b[t.dataset.editBlock]=t.value;}persist();render();return;}
 if(t.id==='stageFilter'){ui.syllabusStage=t.value;render();return;}
 if(t.id==='logDate'){ui.logDate=t.value;render();return;}
 if(t.id==='noteDate'){ui.noteDate=t.value;render();return;}
 if(t.id==='dailyTarget'){state.settings.dailyGoal=Math.max(60,Math.round(Number(t.value)*60)||480);persist();render();return;}
}
function handleInput(e){const t=e.target;
 if(t.id==='syllabusSearch'){ui.syllabusSearch=t.value;const start=t.selectionStart;render();const input=$('#syllabusSearch');input?.focus();input?.setSelectionRange(start,start);return;}
 if(['dailyPriority','dailyText','dailyWin'].includes(t.id)){const n=noteEntryMutable(ui.noteDate);const key={dailyPriority:'priority',dailyText:'text',dailyWin:'win'}[t.id];n[key]=t.value;persist();return;}
 if(['weekFocus','weekNote'].includes(t.id)){state.weeks[ui.week-1][t.id==='weekFocus'?'focus':'note']=t.value;persist();return;}
}
function handleSubmit(e){const f=e.target;if(!['manualLogForm','syllabusForm','weekForm'].includes(f.id))return;e.preventDefault();const data=new FormData(f);
 if(f.id==='manualLogForm'){const minutes=Number(data.get('hours'))*60+Number(data.get('minutes'));if(!Number.isFinite(minutes)||minutes<1||minutes>1440){alert('Please enter a duration between 1 minute and 24 hours.');return;}const entry={id:data.get('id')||uid(),date:String(data.get('date')),category:String(data.get('category')),label:String(data.get('label')).trim().slice(0,200),minutes:Math.round(minutes),itemId:String(data.get('itemId')||''),source:'manual',createdAt:new Date().toISOString()};if(!entry.label||!/\d{4}-\d{2}-\d{2}/.test(entry.date)){alert('Please check the activity name and date.');return;}const i=state.logs.findIndex(x=>x.id===entry.id);if(i>=0){entry.createdAt=state.logs[i].createdAt;state.logs[i]=entry}else state.logs.push(entry);persist();closeModal();render();toast('Activity time saved.');}
 if(f.id==='syllabusForm'){let x=syllabusItem(data.get('id'));if(!x)return;x.title=String(data.get('title')).trim();x.minutes=Math.max(5,Math.min(2000,Number(data.get('minutes'))||x.minutes));x.note=String(data.get('note')||'');x.completed=data.has('completed');x.completedAt=x.completed?x.completedAt||new Date().toISOString():null;persist();closeModal();render();toast('GRE topic updated.');}
 if(f.id==='weekForm'){let w=state.weeks[ui.week-1];const q=data.getAll('quant').map(Number),v=data.getAll('verbal').map(Number),fd=data.getAll('foundation').map(Number);state.weeks.forEach(x=>{if(x.id!==w.id){x.q=x.q.filter(n=>!q.includes(n));x.v=x.v.filter(n=>!v.includes(n));x.f=x.f.filter(n=>!fd.includes(n));}});w.q=q;w.v=v;w.f=fd;persist();closeModal();render();toast('Weekly plan updated.');}
}
async function startApp(){try{state=await load();if(!state.dateAssignments)state.dateAssignments={};const oldScheduled=scheduledForDate;scheduledForDate=function(date){const key=state.dateAssignments?.[date]||state.assignment[weekday(date)]||'morning';return {key,...(state.templates[key]||state.templates.morning)};};
 document.addEventListener('click',handleClick);document.addEventListener('change',handleChange);document.addEventListener('input',handleInput);document.addEventListener('submit',handleSubmit);
 $('#menuBtn').addEventListener('click',()=>$('#sidebar').classList.toggle('shown'));$('#topQuickAdd').addEventListener('click',()=>logModal());window.addEventListener('beforeunload',flushSave);setInterval(refreshTimerDisplay,1000);render();
 if('serviceWorker' in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
 }catch(err){console.error('Failed to initialize Focus Atlas',err);$('#view').innerHTML=`<section class="card"><h2>Could not open workspace</h2><p>${esc(err.message)}</p><p>Try opening the file in a modern browser. Your existing data has not intentionally been deleted.</p></section>`;}}
startApp();
